/// Per-tab field groups for the eleven editor tabs.
///
/// The catalogue is generated by `tool/gen_field_groups.dart` from
/// `assets/schema/gamedata_110.json` into `assets/fields/groups.json`. It never
/// invents a field name: every [FieldRef] carries a name and hash that the schema
/// verified, and unnamed fields are represented only as counts or as name-free
/// [OpaqueFieldRef] hashes.
///
/// This library is pure Dart and imports no Flutter libraries.
library;

import 'dart:convert';

import '../schema/gamedata_schema.dart';

/// The eleven tab ids rendered by the editor, in display order.
enum EditorTabGroup {
  /// Headline save scalars.
  overview('overview', 'Overview'),

  /// Saved position, scene, age, and map markers.
  playerWorld('playerWorld', 'Player & World'),

  /// Item acquisition, pouch, bottles, ammo, and counts.
  inventory('inventory', 'Inventory'),

  /// Equipped slots and equipment state.
  equipment('equipment', 'Equipment'),

  /// Life, magic, rupees, counts, and capacity upgrades.
  resources('resources', 'Resources'),

  /// Events, quests, stones, sages, and songs.
  progression('progression', 'Progression'),

  /// Dungeon item flags, keys, bosses, and heart containers.
  dungeons('dungeons', 'Dungeons'),

  /// Skulltula tokens, heart pieces, beans, poes, fishing, scores.
  collectibles('collectibles', 'Collectibles'),

  /// All Bool flags as prefix buckets and counts.
  flags('flags', 'Flags'),

  /// Hash-only counts and opaque binary hashes.
  advanced('advanced', 'Advanced'),

  /// Application settings (no save fields).
  settings('settings', 'Settings');

  const EditorTabGroup(this.id, this.title);

  /// Stable tab id used by the JSON asset and the UI.
  final String id;

  /// Human-readable tab title.
  final String title;

  /// Resolves a tab id, or `null` when it is not one of the eleven tabs.
  static EditorTabGroup? fromId(String id) {
    for (final tab in values) {
      if (tab.id == id) {
        return tab;
      }
    }
    return null;
  }
}

/// How strongly a group member or group is evidenced.
enum FieldProvenance {
  /// Name, type, section, and record position were verified against the schema;
  /// semantic names backed by host code or the BYML struct table.
  verified,

  /// Verified, and the decoded value also differed across the three sample saves.
  observed,

  /// The name pattern is hash-verified but the meaning is inferred from the name
  /// only; no host-code or struct-table confirmation exists.
  inferred;

  /// Parses the JSON wire name.
  static FieldProvenance parse(String value) {
    return switch (value) {
      'verified' => FieldProvenance.verified,
      'observed' => FieldProvenance.observed,
      'inferred' => FieldProvenance.inferred,
      _ => throw FormatException('unknown field provenance: $value'),
    };
  }
}

/// One real, named, on-disk field in a group.
final class FieldRef {
  /// Creates a field reference.
  const FieldRef({
    required this.hash,
    required this.name,
    required this.type,
    required this.section,
    required this.defaultPreview,
    required this.provenance,
  });

  /// Murmur3_x86_32 of [name], the on-disk record key.
  final int hash;

  /// The verified full field name from the schema.
  final String name;

  /// The schema wire type, such as `Int`, `Bool`, or `String64`.
  final String type;

  /// The schema section id (`1..32`), or `null` when not applicable.
  final int? section;

  /// A deterministic preview of the schema default.
  final String defaultPreview;

  /// Evidence level for this field.
  final FieldProvenance provenance;

  /// Lower-case eight-digit hash, for example `0x31ab5580`.
  String get hashHex => formatFieldHash(hash);

  @override
  String toString() => 'FieldRef($name, $type, $hashHex)';
}

/// One named prefix or wire-type bucket, used by the flags and advanced tabs.
final class FieldBucket {
  /// Creates a bucket summary.
  const FieldBucket({
    required this.id,
    required this.label,
    required this.type,
    required this.namedCount,
    required this.unnamedCount,
    required this.totalCount,
    this.prefix,
    this.samples = const <String>[],
  });

  /// Stable bucket id, such as `flags.prefix.HavePlayedEvent`.
  final String id;

  /// Display label. For a prefix bucket this is the verified name prefix.
  final String label;

  /// Optional name prefix for flags buckets.
  final String? prefix;

  /// The wire type this bucket counts.
  final String type;

  /// Number of named fields in the bucket.
  final int namedCount;

  /// Number of hash-only fields in the bucket.
  final int unnamedCount;

  /// Total field count in the bucket.
  final int totalCount;

  /// Up to three real field names, when the bucket has named members.
  final List<String> samples;

  @override
  String toString() =>
      'FieldBucket($id, $namedCount named, $unnamedCount unnamed)';
}

/// A name-free reference to an opaque, hash-only field.
///
/// The UI must present this as a hash, never as a fabricated label.
final class OpaqueFieldRef {
  /// Creates an opaque hash reference.
  const OpaqueFieldRef({
    required this.hash,
    required this.type,
    required this.section,
    required this.defaultPreview,
    required this.recordIndex,
  });

  /// The on-disk record key.
  final int hash;

  /// The opaque wire type (`Binary`, `BinaryArray`, or `WString16Array`).
  final String type;

  /// The schema section id.
  final int? section;

  /// A deterministic preview of the schema default.
  final String defaultPreview;

  /// Raw record index, or `null` when not on disk.
  final int? recordIndex;

  /// Lower-case eight-digit hash, for example `0x1ca2d1b7`.
  String get hashHex => formatFieldHash(hash);

  @override
  String toString() => 'OpaqueFieldRef($type, $hashHex)';
}

/// One named group of fields inside a tab.
final class FieldGroup {
  /// Creates a group and freezes its lists.
  FieldGroup({
    required this.id,
    required this.title,
    required this.description,
    required this.provenance,
    required Iterable<FieldRef> fields,
    required this.unnamedCount,
    required this.caveat,
    required Iterable<String> matchRules,
    Iterable<FieldBucket> buckets = const <FieldBucket>[],
    Iterable<OpaqueFieldRef> opaqueFields = const <OpaqueFieldRef>[],
  }) : fields = List<FieldRef>.unmodifiable(fields),
       matchRules = List<String>.unmodifiable(matchRules),
       buckets = List<FieldBucket>.unmodifiable(buckets),
       opaqueFields = List<OpaqueFieldRef>.unmodifiable(opaqueFields);

  /// Stable group id, unique across the whole catalogue.
  final String id;

  /// Human-readable group title.
  final String title;

  /// What the group contains and how it is meant to be used.
  final String description;

  /// Strongest evidence carried by the group.
  final FieldProvenance provenance;

  /// Named fields in this group, sorted by name.
  final List<FieldRef> fields;

  /// Count of matching hash-only fields that are not named in this group.
  final int unnamedCount;

  /// Honest limitation shown with the group, or `null`.
  final String? caveat;

  /// The documented generator rules that produced this group.
  final List<String> matchRules;

  /// Counts for flags and advanced groups; empty for curated groups.
  final List<FieldBucket> buckets;

  /// Opaque name-free references; only the advanced tab uses these.
  final List<OpaqueFieldRef> opaqueFields;

  /// Number of named field references.
  int get namedCount => fields.length;

  /// Number of named plus hash-only fields represented by this group.
  int get totalCount => fields.length + unnamedCount;

  @override
  String toString() =>
      'FieldGroup($id, ${fields.length} named, $unnamedCount unnamed)';
}

/// Per-tab counts derived by the generator.
final class TabStats {
  /// Creates tab stats.
  const TabStats({
    required this.tab,
    required this.named,
    required this.unnamed,
    required this.groups,
    required this.caveat,
  });

  /// The tab these counts describe.
  final EditorTabGroup tab;

  /// Distinct named fields in the tab.
  final int named;

  /// Hash-only fields counted by the tab.
  final int unnamed;

  /// Number of groups in the tab.
  final int groups;

  /// The tab's honest limitation statement.
  final String caveat;

  /// Named plus hash-only fields represented by the tab.
  int get total => named + unnamed;

  @override
  String toString() => 'TabStats(${tab.id}, $named named, $unnamed unnamed)';
}

/// Catalogue-wide counts, including the per-tab table.
final class CatalogueStats {
  /// Creates stats and indexes them by tab.
  CatalogueStats({
    required this.schemaRevision,
    required this.schemaRevisionHex,
    required this.onDiskFields,
    required this.namedFields,
    required this.unnamedFields,
    required this.observedFields,
    required Iterable<TabStats> tabs,
  }) : tabs = List<TabStats>.unmodifiable(tabs) {
    final index = <EditorTabGroup, TabStats>{};
    for (final tab in this.tabs) {
      if (index.containsKey(tab.tab)) {
        throw FormatException('duplicate tab stats: ${tab.tab.id}');
      }
      index[tab.tab] = tab;
    }
    for (final tab in EditorTabGroup.values) {
      if (!index.containsKey(tab)) {
        throw FormatException('missing tab stats: ${tab.id}');
      }
    }
    _byTab = Map<EditorTabGroup, TabStats>.unmodifiable(index);
  }

  /// The schema revision the catalogue was generated from.
  final int schemaRevision;

  /// The revision in lower-case hex (`0x2d80eb`).
  final String schemaRevisionHex;

  /// Total on-disk fields in the schema.
  final int onDiskFields;

  /// Fields with a recovered verified name.
  final int namedFields;

  /// Fields without a recovered name.
  final int unnamedFields;

  /// Named fields observed to differ across the three sample saves.
  final int observedFields;

  /// Per-tab rows in [EditorTabGroup] order.
  final List<TabStats> tabs;

  late final Map<EditorTabGroup, TabStats> _byTab;

  /// Returns the stats row for [tab].
  TabStats forTab(EditorTabGroup tab) => _byTab[tab]!;

  @override
  String toString() =>
      'CatalogueStats($onDiskFields on disk, $namedFields named, '
      '$unnamedFields unnamed)';
}

/// The complete per-tab field-group catalogue.
final class FieldGroupsCatalogue {
  FieldGroupsCatalogue._({
    required Map<String, Object?> schema,
    required this.stats,
    required Map<EditorTabGroup, List<FieldGroup>> tabs,
    required Iterable<OpaqueFieldRef> opaqueFields,
  }) : schema = Map<String, Object?>.unmodifiable(schema),
       _tabs = Map<EditorTabGroup, List<FieldGroup>>.unmodifiable(tabs),
       _opaqueFields = List<OpaqueFieldRef>.unmodifiable(opaqueFields) {
    _index();
  }

  /// Loads and validates a catalogue from JSON text.
  factory FieldGroupsCatalogue.load(String jsonSource) {
    final decoded = jsonDecode(jsonSource);
    if (decoded is! Map<String, Object?>) {
      throw const FormatException('field groups: expected a JSON object');
    }
    return FieldGroupsCatalogue.fromJson(decoded);
  }

  /// Loads and validates an already-decoded catalogue object.
  factory FieldGroupsCatalogue.fromJson(Map<String, Object?> json) {
    final schema = _object(json['schema'], 'schema');
    final revision = _int(schema, 'revision');
    if (revision != gamedataSchemaRevision) {
      throw FormatException(
        'field groups: schema revision ${formatFieldHash(revision)} does not '
        'match ${formatFieldHash(gamedataSchemaRevision)}',
      );
    }
    final revisionHex = _string(schema, 'revisionHex');
    if (revisionHex != revisionHexOf(revision)) {
      throw FormatException(
        'field groups: revisionHex $revisionHex does not match '
        '${revisionHexOf(revision)}',
      );
    }
    final onDiskFields = _int(schema, 'onDiskFields');
    final namedFields = _int(schema, 'namedFields');
    final unnamedFields = _int(schema, 'unnamedFields');
    if (namedFields + unnamedFields != onDiskFields) {
      throw const FormatException(
        'field groups: named + unnamed does not equal onDiskFields',
      );
    }

    final tabsJson = _objectList(json['tabs'], 'tabs');
    if (tabsJson.length != EditorTabGroup.values.length) {
      throw FormatException(
        'field groups: expected ${EditorTabGroup.values.length} tabs, '
        'got ${tabsJson.length}',
      );
    }
    final tabs = <EditorTabGroup, List<FieldGroup>>{};
    final groupIds = <String>{};
    final opaque = <int, OpaqueFieldRef>{};
    for (final tabJson in tabsJson) {
      final id = _string(tabJson, 'id');
      final tab = EditorTabGroup.fromId(id);
      if (tab == null) {
        throw FormatException('field groups: unknown tab id $id');
      }
      if (tabs.containsKey(tab)) {
        throw FormatException('field groups: duplicate tab $id');
      }
      final groupsJson = _objectList(tabJson['groups'], '$id.groups');
      if (groupsJson.isEmpty) {
        throw FormatException('field groups: tab $id has no groups');
      }
      final groups = <FieldGroup>[];
      for (final groupJson in groupsJson) {
        final group = _groupFromJson(groupJson);
        if (!groupIds.add(group.id)) {
          throw FormatException('field groups: duplicate group ${group.id}');
        }
        groups.add(group);
        for (final opaqueField in group.opaqueFields) {
          final previous = opaque[opaqueField.hash];
          if (previous != null &&
              (previous.type != opaqueField.type ||
                  previous.section != opaqueField.section)) {
            throw FormatException(
              'field groups: conflicting opaque hash ${opaqueField.hashHex}',
            );
          }
          opaque[opaqueField.hash] = opaqueField;
        }
      }
      tabs[tab] = List<FieldGroup>.unmodifiable(groups);
    }
    final tabOrder = tabs.keys.toList();
    for (var index = 0; index < EditorTabGroup.values.length; index++) {
      if (tabOrder[index] != EditorTabGroup.values[index]) {
        throw const FormatException(
          'field groups: tabs are not in EditorTabGroup order',
        );
      }
    }

    final stats = _statsFromJson(_object(json['stats'], 'stats'));
    if (stats.schemaRevision != revision ||
        stats.schemaRevisionHex != revisionHex ||
        stats.onDiskFields != onDiskFields ||
        stats.namedFields != namedFields ||
        stats.unnamedFields != unnamedFields) {
      throw const FormatException(
        'field groups: stats header does not match the schema block',
      );
    }
    for (final tab in EditorTabGroup.values) {
      final row = stats.forTab(tab);
      final groups = tabs[tab]!;
      final hashes = <int>{};
      var unnamed = 0;
      for (final group in groups) {
        hashes.addAll(group.fields.map((field) => field.hash));
        unnamed += group.unnamedCount;
      }
      if (row.named != hashes.length ||
          row.unnamed != unnamed ||
          row.groups != groups.length) {
        throw FormatException(
          'field groups: stats for ${tab.id} do not match the groups',
        );
      }
    }
    final advanced = tabs[EditorTabGroup.advanced]!;
    final advancedUnnamed = advanced.fold<int>(
      0,
      (total, group) => total + group.unnamedCount,
    );
    if (advancedUnnamed != unnamedFields) {
      throw FormatException(
        'field groups: advanced unnamed count $advancedUnnamed does not match '
        '$unnamedFields',
      );
    }

    return FieldGroupsCatalogue._(
      schema: schema,
      stats: stats,
      tabs: tabs,
      opaqueFields: opaque.values,
    );
  }

  /// Provenance metadata copied from the generated asset.
  final Map<String, Object?> schema;

  /// Derived per-tab and catalogue-wide counts.
  final CatalogueStats stats;

  final Map<EditorTabGroup, List<FieldGroup>> _tabs;
  final List<OpaqueFieldRef> _opaqueFields;
  late final Map<int, FieldRef> _byHash;
  late final Map<String, FieldRef> _byName;
  late final List<FieldRef> _allFields;
  late final Map<String, FieldGroup> _byGroupId;

  /// Every group in tab order, then generator order.
  List<FieldGroup> get groups => List<FieldGroup>.unmodifiable(<FieldGroup>[
    for (final tab in EditorTabGroup.values) ..._tabs[tab]!,
  ]);

  /// Every distinct named field, sorted by name.
  List<FieldRef> get fields => _allFields;

  /// Lookup by verified full name.
  Map<String, FieldRef> get byName => _byName;

  /// Lookup by on-disk hash.
  Map<int, FieldRef> get byHash => _byHash;

  /// Opaque name-free hashes from the advanced tab.
  List<OpaqueFieldRef> get opaqueFields => _opaqueFields;

  /// Groups belonging to [tab], in generator order.
  List<FieldGroup> forTab(EditorTabGroup tab) => _tabs[tab]!;

  /// The group with [id], or `null`.
  FieldGroup? groupById(String id) => _byGroupId[id];

  /// Flags prefix buckets, including the hash-only Bool bucket.
  List<FieldBucket> get flagBuckets {
    return List<FieldBucket>.unmodifiable(<FieldBucket>[
      for (final group in forTab(EditorTabGroup.flags)) ...group.buckets,
    ]);
  }

  /// The flags bucket for [prefix], or `null`.
  FieldBucket? flagBucket(String prefix) {
    for (final bucket in flagBuckets) {
      if (bucket.prefix == prefix) {
        return bucket;
      }
    }
    return null;
  }

  /// Named flags whose bucket prefix is [prefix].
  List<FieldRef> flagFieldsUnder(String prefix) {
    return List<FieldRef>.unmodifiable(<FieldRef>[
      for (final field in forTab(
        EditorTabGroup.flags,
      ).expand((group) => group.fields))
        if (flagPrefixOf(field.name) == prefix) field,
    ]);
  }

  /// Hash-only Bool count from the `flags.unnamedBool` bucket.
  int get unnamedBoolCount {
    for (final bucket in flagBuckets) {
      if (bucket.id == 'flags.unnamedBool') {
        return bucket.unnamedCount;
      }
    }
    return 0;
  }

  /// Case- and diacritic-insensitive search over names, name prefixes, and
  /// hashes. The query `0x31ab5580` matches the field with that hash.
  List<FieldRef> search(String query) {
    final trimmed = query.trim();
    if (trimmed.isEmpty) {
      return const <FieldRef>[];
    }
    final needle = _fold(trimmed);
    final hashNeedle = trimmed.toLowerCase().replaceFirst(RegExp('^0x'), '');
    final isHex = RegExp(r'^[0-9a-f]+$').hasMatch(hashNeedle);
    final matches = <int, FieldRef>{};
    for (final field in _allFields) {
      final foldedName = _fold(field.name);
      final prefixHit =
          foldedName.startsWith(needle) ||
          foldedName.split('.').any((segment) => segment.startsWith(needle));
      final nameHit = foldedName.contains(needle);
      final hashHit = isHex && field.hashHex.contains(hashNeedle);
      if (nameHit || prefixHit || hashHit) {
        matches[field.hash] = field;
      }
    }
    final result = matches.values.toList()
      ..sort((a, b) {
        final byName = _fold(a.name).compareTo(_fold(b.name));
        return byName != 0 ? byName : a.hash.compareTo(b.hash);
      });
    return List<FieldRef>.unmodifiable(result);
  }

  void _index() {
    final byHash = <int, FieldRef>{};
    final byName = <String, FieldRef>{};
    final byGroupId = <String, FieldGroup>{};
    for (final tab in EditorTabGroup.values) {
      for (final group in _tabs[tab]!) {
        if (byGroupId.containsKey(group.id)) {
          throw FormatException('duplicate group id: ${group.id}');
        }
        byGroupId[group.id] = group;
        for (final field in group.fields) {
          final previousHash = byHash[field.hash];
          if (previousHash != null && previousHash.name != field.name) {
            throw FormatException(
              'hash ${field.hashHex} maps to both ${previousHash.name} and '
              '${field.name}',
            );
          }
          final previousName = byName[field.name];
          if (previousName != null && previousName.hash != field.hash) {
            throw FormatException(
              'name ${field.name} maps to both ${previousName.hashHex} and '
              '${field.hashHex}',
            );
          }
          byHash[field.hash] = field;
          byName[field.name] = field;
        }
      }
    }
    final all = byHash.values.toList()
      ..sort((a, b) {
        final folded = _fold(a.name).compareTo(_fold(b.name));
        return folded != 0 ? folded : a.hash.compareTo(b.hash);
      });
    _byHash = Map<int, FieldRef>.unmodifiable(byHash);
    _byName = Map<String, FieldRef>.unmodifiable(byName);
    _allFields = List<FieldRef>.unmodifiable(all);
    _byGroupId = Map<String, FieldGroup>.unmodifiable(byGroupId);
  }

  @override
  String toString() =>
      'FieldGroupsCatalogue(${_tabs.length} tabs, ${_allFields.length} named '
      'fields)';
}

/// Formats [hash] as lower-case `0x` plus eight hex digits.
String formatFieldHash(int hash) =>
    '0x${hash.toRadixString(16).padLeft(8, '0')}';

/// Formats a schema revision as lower-case `0x` plus hex digits.
String revisionHexOf(int revision) =>
    '0x${revision.toRadixString(16).padLeft(6, '0')}';

/// The bucket prefix rule used by the flags tab.
///
/// The first dot segment wins, then the first underscore segment. A name with
/// neither separator belongs to `(other)`. This is deliberately the same rule
/// used by the generator, so `flagFieldsUnder(bucket.prefix!)` is complete.
String flagPrefixOf(String name) {
  final dot = name.indexOf('.');
  if (dot >= 0) {
    return name.substring(0, dot);
  }
  final underscore = name.indexOf('_');
  if (underscore >= 0) {
    return name.substring(0, underscore);
  }
  return '(other)';
}

FieldGroup _groupFromJson(Map<String, Object?> json) {
  final id = _string(json, 'id');
  final fieldsJson = _objectList(json['fields'], '$id.fields');
  final fields = <FieldRef>[];
  final hashes = <int>{};
  for (final fieldJson in fieldsJson) {
    final field = _fieldFromJson(fieldJson, id);
    if (!hashes.add(field.hash)) {
      throw FormatException('$id: duplicate field hash ${field.hashHex}');
    }
    fields.add(field);
  }
  final buckets = <FieldBucket>[
    for (final bucketJson in _objectList(json['buckets'], '$id.buckets'))
      _bucketFromJson(bucketJson, id),
  ];
  if (buckets.isNotEmpty) {
    final bucketNamed = buckets.fold<int>(
      0,
      (total, bucket) => total + bucket.namedCount,
    );
    final bucketUnnamed = buckets.fold<int>(
      0,
      (total, bucket) => total + bucket.unnamedCount,
    );
    if (bucketNamed != fields.length) {
      throw FormatException(
        '$id: bucket named count $bucketNamed does not match '
        '${fields.length} fields',
      );
    }
    if (bucketUnnamed != _int(json, 'unnamedCount')) {
      throw FormatException(
        '$id: bucket unnamed count $bucketUnnamed does not match '
        'unnamedCount',
      );
    }
  }
  final opaque = <OpaqueFieldRef>[
    for (final opaqueJson in _objectList(
      json['opaqueFields'],
      '$id.opaqueFields',
    ))
      _opaqueFromJson(opaqueJson, id),
  ];
  final unnamedCount = _int(json, 'unnamedCount');
  if (unnamedCount < 0) {
    throw FormatException('$id: negative unnamedCount');
  }
  final group = FieldGroup(
    id: id,
    title: _string(json, 'title'),
    description: _string(json, 'description'),
    provenance: FieldProvenance.parse(_string(json, 'provenance')),
    fields: fields,
    unnamedCount: unnamedCount,
    caveat: _nullableString(json['caveat'], '$id.caveat'),
    matchRules: _stringList(json['matchRules'], '$id.matchRules'),
    buckets: buckets,
    opaqueFields: opaque,
  );
  if (group.fields.isEmpty &&
      group.unnamedCount == 0 &&
      group.buckets.isEmpty &&
      group.opaqueFields.isEmpty &&
      id != 'settings.appSettings' &&
      id != 'progression.medallions') {
    throw FormatException('$id: empty group is not an allowed placeholder');
  }
  return group;
}

FieldRef _fieldFromJson(Map<String, Object?> json, String groupId) {
  final name = _string(json, 'name');
  if (name.isEmpty) {
    throw FormatException('$groupId: empty field name');
  }
  final hash = _int(json, 'hash');
  if (hash < 0 || hash > 0xffffffff) {
    throw FormatException('$groupId: hash $hash is not 32-bit');
  }
  final hashHex = _string(json, 'hashHex');
  if (hashHex != formatFieldHash(hash)) {
    throw FormatException('$groupId: hashHex $hashHex does not match $hash');
  }
  final type = _string(json, 'type');
  if (SaveType.fromWireName(type) == null) {
    throw FormatException('$groupId: unknown field type $type');
  }
  final section = _nullableInt(json['section'], '$groupId.section');
  if (section != null && (section < 0 || section > 32)) {
    throw FormatException('$groupId: section $section is out of range');
  }
  final preview = _string(json, 'defaultPreview');
  if (preview.isEmpty) {
    throw FormatException('$groupId: empty defaultPreview for $name');
  }
  return FieldRef(
    hash: hash,
    name: name,
    type: type,
    section: section,
    defaultPreview: preview,
    provenance: FieldProvenance.parse(_string(json, 'provenance')),
  );
}

FieldBucket _bucketFromJson(Map<String, Object?> json, String groupId) {
  final named = _int(json, 'namedCount');
  final unnamed = _int(json, 'unnamedCount');
  final total = _int(json, 'totalCount');
  if (named < 0 || unnamed < 0 || total < 0) {
    throw FormatException('$groupId: negative bucket count');
  }
  if (named + unnamed != total) {
    throw FormatException(
      '$groupId: bucket counts $named + $unnamed != $total',
    );
  }
  return FieldBucket(
    id: _string(json, 'id'),
    label: _string(json, 'label'),
    prefix: _nullableString(json['prefix'], '$groupId.bucket.prefix'),
    type: _string(json, 'type'),
    namedCount: named,
    unnamedCount: unnamed,
    totalCount: total,
    samples: _stringList(json['samples'], '$groupId.bucket.samples'),
  );
}

OpaqueFieldRef _opaqueFromJson(Map<String, Object?> json, String groupId) {
  final hash = _int(json, 'hash');
  if (hash < 0 || hash > 0xffffffff) {
    throw FormatException('$groupId: opaque hash $hash is not 32-bit');
  }
  final hashHex = _string(json, 'hashHex');
  if (hashHex != formatFieldHash(hash)) {
    throw FormatException('$groupId: opaque hashHex does not match $hash');
  }
  final type = _string(json, 'type');
  if (type != 'Binary' && type != 'BinaryArray' && type != 'WString16Array') {
    throw FormatException('$groupId: unsupported opaque type $type');
  }
  final section = _nullableInt(json['section'], '$groupId.opaque.section');
  if (section != null && (section < 0 || section > 32)) {
    throw FormatException('$groupId: opaque section $section is out of range');
  }
  return OpaqueFieldRef(
    hash: hash,
    type: type,
    section: section,
    defaultPreview: _string(json, 'defaultPreview'),
    recordIndex: _nullableInt(
      json['recordIndex'],
      '$groupId.opaque.recordIndex',
    ),
  );
}

CatalogueStats _statsFromJson(Map<String, Object?> json) {
  final tabsJson = _objectList(json['tabs'], 'stats.tabs');
  final tabs = <TabStats>[];
  for (final tabJson in tabsJson) {
    final id = _string(tabJson, 'id');
    final tab = EditorTabGroup.fromId(id);
    if (tab == null) {
      throw FormatException('stats: unknown tab id $id');
    }
    tabs.add(
      TabStats(
        tab: tab,
        named: _int(tabJson, 'named'),
        unnamed: _int(tabJson, 'unnamed'),
        groups: _int(tabJson, 'groups'),
        caveat: _string(tabJson, 'caveat'),
      ),
    );
  }
  return CatalogueStats(
    schemaRevision: _int(json, 'schemaRevision'),
    schemaRevisionHex: _string(json, 'schemaRevisionHex'),
    onDiskFields: _int(json, 'onDiskFields'),
    namedFields: _int(json, 'namedFields'),
    unnamedFields: _int(json, 'unnamedFields'),
    observedFields: _int(json, 'observedFields'),
    tabs: tabs,
  );
}

/// Lower-cases and removes common Latin diacritics for search.
String _fold(String value) {
  final lower = value.toLowerCase();
  final buffer = StringBuffer();
  for (final rune in lower.runes) {
    final character = String.fromCharCode(rune);
    buffer.write(_diacritics[character] ?? character);
  }
  return buffer.toString();
}

